package com.pulselens.analytics.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="news_articles") public class NewsArticle {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=500) private String title;@Column(columnDefinition="TEXT") private String description;@Column(columnDefinition="LONGTEXT") private String content;@Column(length=1000) private String url;private String author;private String sourceName;private String categoryName;private String sentiment;private LocalDateTime publishedAt;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();
 public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public String getUrl(){return url;}public void setUrl(String v){url=v;}public String getAuthor(){return author;}public void setAuthor(String v){author=v;}public String getSourceName(){return sourceName;}public void setSourceName(String v){sourceName=v;}public String getCategoryName(){return categoryName;}public void setCategoryName(String v){categoryName=v;}public String getSentiment(){return sentiment;}public void setSentiment(String v){sentiment=v;}public LocalDateTime getPublishedAt(){return publishedAt;}public void setPublishedAt(LocalDateTime v){publishedAt=v;}public LocalDateTime getCreatedAt(){return createdAt;}
}
